from collections import Counter
def f(g):
    res=[]
    for row in g:
        c=Counter(row)
        if len(c)>1:
            others=[v for v,_ in c.most_common() if v!=c.most_common(1)[0][0]]
            res.append([1 if v in others else v for v in row])
        else:
            res.append(row)
    return res
